201	    fn drain_notifiers(&mut self) {
202	        let decided = self.op.get_decided_idx();
203	        let now = Instant::now();
204	        let cur_ballot = self.op.get_promise();
205	        let old = std::mem::take(&mut self.pending);
206	        for p in old {
207	            match p.assigned {
208	                Some((idx, _)) if idx <= decided => {
209	                    let _ = p.reply.send(Ok(idx));
210	                }
211	                Some((idx, ballot)) if ballot < cur_ballot => {
212	                    let _ = p
213	                        .reply
214	                        .send(Err(AppendError::Superseded { log_entry_idx: idx }));
215	                }
216	                _ if now > p.deadline => {
217	                    let _ = p.reply.send(Err(AppendError::Timeout));
218	                }
219	                _ => self.pending.push_back(p),
220	            }
221	        }
222	    }
